def f(g):
    H=len(g); W=len(g[0])
    bg=Counter([v for row in g for v in row]).most_common(1)[0][0]
    cols={}
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg: cols.setdefault(g[r][c],[]).append((r,c))
    out=[row[:] for row in g]
    for x,pts in cols.items():
        for i,(a,b) in enumerate(pts):
            # directions along diagonals; find line through a-b others
            cand=[]
            for dr,dc in [(1,1),(1,-1),(-1,1),(-1,-1)]:
                cells_on=[]
                r,c=a+dr,b+dc
                while 0<=r<H and 0<=c<W and g[r][c]==x:
                    cells_on.append((r,c)); r+=dr; c+=dc
                r,c=a-dr,b-dc
                while 0<=r<H and 0<=c<W and g[r][c]==x:
                    cells_on.append((r,c)); r-=dr; c-=dc
                if len(cells_on)>=2: cand.append((dr,dc,cells_on[-1]))
            # horizontal line
            horiz=[]
            r,c=a+1,b
            while 0<=r<H and g[r][c]==x: horiz.append((r,c)); r+=1
            r,c=a-1,b
            while 0<=r<H and g[r][c]==x: horiz.append((r,c)); r-=1
            if len(horiz)>=2: cand.append(('H',0,a))
            vert=[]
            c,r=a,b+1
            while 0<=c<W and g[r][c]==x: vert.append((r,c)); r+=1
            c,r=a,b-1
            while 0<=c<W and g[r][c]==x: vert.append((r,c)); r-=1
            if len(vert)>=2: cand.append(('V',0,a))
            if cand:
                continue
            # no line found -> single cell; check diagonal neighbors
            moves=[(1,1),(1,-1)]
            best=None
            for dr,dc in moves:
                r,c=a+dr,b+dc
                run=0
                while 0<=r<H and 0<=c<W and g[r][c]==x:
                    run+=1; r+=dr; c+=dc
                if run==0: continue
                r,c=a-dr,b-dc
                runb=0
                while 0<=r<H and 0<=c<W and g[r][c]==x:
                    runb+=1; r-=dr; c-=dc
                if runb==0: continue
                # extend into direction whose path is shorter/blocked side? pick direction with blocked other end
                if runb>run: best=('down',dr,dc)
                else: best=('up',-dr,-dc)
            if best:
                drr,dcc,_ = best
                r,c=a+drr,b+dcc
                while 0<=r<H and 0<=c<W and g[r][c]==bg:
                    out[r][c]=x; r+=drr; c+=dcc
    return out
